import React from "react";
import type { StickerProps } from "../../types";
import { AnimatedSticker } from "../../components/AnimatedSticker";

// Exact reference pixels embedded as a lossless PNG — same technique as CatbeatsSticker.
const IMAGE = "data:image/png;base64,";

/**
 * Spooky Bigfoot Sticker — reproduced from the original Dribbble reference artwork.
 * Text, if any, is baked into the artwork and is not configurable.
 */
export const SpookyBigfootSticker: React.FC<StickerProps> = (props) => (
  <AnimatedSticker
    {...props}
    label="Spooky Bigfoot Sticker"
    viewBox="0 0 247 320"
    motion="sway"
    duration={4}
    origin="124px 320px"
  >
    <image href={IMAGE} x={0} y={0} width={247} height={320} />
  </AnimatedSticker>
);

export default SpookyBigfootSticker;
